import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { COMMUNITY_NAME_PATTERN, COMMUNITY_NAME_RULE, POSTING_POLICIES, POSTING_POLICY_LABELS, REMOVAL_REASON_LABELS } from "./community.js";

// The runtime rules must match the API's OpenAPI document (regenerated by `pnpm sdk`).
interface Property {
  pattern?: string;
  description?: string;
  enum?: string[];
}
const openapi = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as {
  paths: Record<string, { post: { description?: string; requestBody: { content: { "application/json": { schema: { properties: Record<string, Property> } } } } } }>;
  components: { schemas: Record<string, { properties: Record<string, Property> }> };
};
const create = openapi.paths["/v1/communities"]!.post.requestBody.content["application/json"].schema.properties;

describe("creating a community", () => {
  it("checks names as the API does, and states the rule in its words", () => {
    expect(COMMUNITY_NAME_PATTERN.source).toBe(create.name!.pattern);
    expect(create.name!.description).toContain(COMMUNITY_NAME_RULE);
    expect(COMMUNITY_NAME_PATTERN.test("rust")).toBe(true);
    expect(COMMUNITY_NAME_PATTERN.test("Rust")).toBe(false);
    expect(COMMUNITY_NAME_PATTERN.test("ab")).toBe(false);
  });

  it("knows every posting policy, each with a label", () => {
    expect([...POSTING_POLICIES].sort()).toEqual([...create.postingPolicy!.enum!].sort());
    expect(Object.keys(POSTING_POLICY_LABELS).sort()).toEqual([...POSTING_POLICIES].sort());
  });
});

describe("removal reasons", () => {
  it("has a label for every report reason, as the API suggests them", () => {
    expect(Object.keys(REMOVAL_REASON_LABELS).sort()).toEqual([...openapi.components.schemas.Report!.properties.reason!.enum!].sort());
    const remove = openapi.paths["/v1/posts/{id}/remove"]!.post.description!;
    for (const label of Object.values(REMOVAL_REASON_LABELS)) expect(remove).toContain(`"${label}"`);
  });
});
